function __installBestScriptHome(actions){
 if(window.__bestScriptHome)return;
 const mount=()=>{
 const nickname=document.getElementById('nickname'),servers=document.getElementById('serverList');
 if(!nickname||!servers)return;
 const style=document.createElement('style');style.id='bs-home-style';style.textContent=`
#bs-home{position:fixed;inset:0;z-index:50;display:flex;align-items:center;justify-content:center;pointer-events:none;contain:layout style;font-family:Arial,sans-serif}#bs-home[hidden]{display:none!important}#bs-home *{box-sizing:border-box}
#bs-home .bs-panel{position:relative;width:min(67vw,160vh,960px);transform:translate(9.5vw,-7vh);aspect-ratio:1235/592;pointer-events:auto;container-type:inline-size}
#bs-home .bs-servers-label{position:absolute;color:#e7dbef;text-shadow:1px 1px #110715;font-weight:900;font-size:2.2cqw;line-height:1;pointer-events:none}#bs-home .bs-filter-defs{position:absolute;width:0;height:0;pointer-events:none}#bs-home .bs-art{position:absolute;inset:0;width:100%;height:100%;filter:none;pointer-events:none;image-rendering:auto}
#bs-home .bs-sprite,#bs-home .bs-discord{position:absolute;display:block;padding:0;margin:0;border:0;background:transparent;cursor:pointer;touch-action:manipulation}
#bs-home .bs-sprite img,#bs-home .bs-discord img{width:100%;height:100%;display:block;pointer-events:none;user-select:none}
#bs-home .bs-play img,#bs-home .bs-official img,#bs-home .bs-community img{filter:none}#bs-home .bs-private img{filter:none}
#bs-home .bs-discord img{filter:none}#bs-home .bs-editor{border:1px solid #8e16c8;border-radius:2px}
#bs-home .bs-play,#bs-home .bs-private{box-shadow:0 0 0 2px #30034b,0 0 0 3px #9a13db,0 0 8px #7c09b6;border-radius:3px}
#bs-home .bs-sprite[aria-pressed=false]{opacity:.82}#bs-home .bs-sprite[aria-pressed=true]{opacity:1}#bs-home .bs-sprite:hover{brightness:1.1}#bs-home .bs-sprite:active{transform:translateY(1px)}#bs-home .bs-sprite:disabled{opacity:.5;cursor:wait}
#bs-home .bs-input-slot{position:absolute}#bs-home #nickname,#bs-home #serverList{position:static!important;inset:auto!important;transform:none!important;width:100%!important;height:100%!important;margin:0!important;padding:0!important;background:none!important;z-index:auto!important;border:0!important;overflow:visible!important}
#bs-home #nicknameInput,#bs-home #servers{width:100%!important;height:100%!important;min-height:0!important;padding:0 4%!important;border:2px solid #252019!important;border-radius:1px!important;box-shadow:inset 0 1px 4px #000a!important;outline:none!important;font-family:Arial,sans-serif!important;font-weight:700!important;font-size:2cqw!important;line-height:normal!important;transform:none!important}
#bs-home #nicknameInput{background:#111416!important;color:#b5bbb5!important;text-align:center!important}#bs-home #nicknameInput::placeholder{color:#9ca59d}#bs-home #servers{background:#c4ae43!important;color:#171711!important;text-shadow:none!important}#bs-home select option{color:#151118;background:#d7c46f}#bs-home .bs-message{position:absolute;margin:0;text-align:center;color:#e9caff;font-size:1.4cqw;line-height:1.2}
#bs-home button:focus-visible,#bs-home a:focus-visible,#bs-home input:focus-visible,#bs-home select:focus-visible{outline:2px solid #e0acff!important;outline-offset:2px}
@media(orientation:portrait){#bs-home .bs-panel{width:calc(100vw - 16px);transform:none}}
`;document.head.appendChild(style);
 const host=document.createElement('section');host.id='bs-home';host.setAttribute('aria-label','BestScript main menu');
 host.innerHTML=`<div class="bs-panel"><svg class="bs-filter-defs" aria-hidden="true"><defs><filter id="bs-metal-purple" color-interpolation-filters="sRGB" x="-2%" y="-4%" width="104%" height="108%"><feColorMatrix in="SourceGraphic" type="saturate" values="0" result="gray"/><feComponentTransfer in="gray" result="dark"><feFuncR type="table" tableValues="0 .008 .025 .06 .10"/><feFuncG type="table" tableValues="0 0 .001 .003 .005"/><feFuncB type="table" tableValues="0 .02 .06 .15 .22"/></feComponentTransfer><feConvolveMatrix in="gray" order="3" kernelMatrix="-1 -1 -1 -1 8 -1 -1 -1 -1" preserveAlpha="true" result="edge"/><feMorphology in="edge" operator="dilate" radius=".8" result="wide"/><feColorMatrix in="wide" type="matrix" values="0 0 0 0 .45 0 0 0 0 .005 0 0 0 0 .70 2 2 2 0 0" result="purple"/><feGaussianBlur in="purple" stdDeviation="2" result="glow"/><feMerge><feMergeNode in="dark"/><feMergeNode in="glow"/><feMergeNode in="purple"/></feMerge></filter><filter id="bs-button-purple" color-interpolation-filters="sRGB"><feColorMatrix type="matrix" values=".529 0 .421 0 0 0 .133 .817 0 0 .765 0 .185 0 0 0 0 0 1 0"/></filter></defs></svg><img class="bs-art" alt="Devast.io" draggable="false" src="data:image/png;base64,"><div class="bs-socials"><a class="bs-discord" href="https://discord.com/invite/nJg9j9sYBC" target="_blank" rel="noopener noreferrer" aria-label="Discord" style="left:3.967611336032389%;top:11.14864864864865%;width:9.7165991902834%;height:20.27027027027027%"><img alt="" src="data:image/png;base64,"></a><a class="bs-discord" href="https://discord.com/invite/nJg9j9sYBC" target="_blank" rel="noopener noreferrer" aria-label="Discord community" style="left:16.599190283400812%;top:11.14864864864865%;width:9.7165991902834%;height:20.27027027027027%"><img alt="" src="data:image/png;base64,"></a></div><button type="button" class="bs-sprite bs-editor" data-action="editor" aria-label="Map editor" title="Map editor"  style="left:3.967611336032389%;top:36.82432432432432%;width:11.336032388663968%;height:19.08783783783784%"><img alt="" draggable="false" src="data:image/png;base64,"></button><button type="button" class="bs-sprite bs-private" data-action="private" aria-label="Private server" title="Private server" aria-pressed="false" style="left:6.477732793522267%;top:57.939189189189186%;width:13.765182186234817%;height:16.216216216216218%"><img alt="" draggable="false" src="data:image/png;base64,"></button><button type="button" class="bs-sprite bs-official" data-action="official" aria-label="Official servers" title="Official servers" aria-pressed="true" style="left:25.263157894736842%;top:44.25675675675676%;width:10.283400809716598%;height:10.641891891891891%"><img alt="" draggable="false" src="data:image/png;base64,"></button><button type="button" class="bs-sprite bs-community" data-action="community" aria-label="Community servers" title="Community servers" aria-pressed="false" style="left:25.263157894736842%;top:56.58783783783784%;width:10.283400809716598%;height:10.641891891891891%"><img alt="" draggable="false" src="data:image/png;base64,"></button><button type="button" class="bs-sprite bs-survival" data-action="survival" aria-label="Survival" title="Survival" aria-pressed="true" style="left:76.92307692307693%;top:44.25675675675676%;width:15.1417004048583%;height:17.39864864864865%"><img alt="" draggable="false" src="data:image/png;base64,"></button><button type="button" class="bs-sprite bs-ghoul" data-action="ghoul" aria-label="Ghoul mode" title="Ghoul mode" aria-pressed="false" style="left:76.92307692307693%;top:63.3445945945946%;width:15.1417004048583%;height:17.39864864864865%"><img alt="" draggable="false" src="data:image/png;base64,"></button><div class="bs-input-slot" data-slot="nickname" style="left:38.38056680161943%;top:44.932432432432435%;width:32.469635627530366%;height:10.472972972972974%"></div><div class="bs-input-slot" data-slot="servers" style="left:38.38056680161943%;top:58.78378378378378%;width:32.469635627530366%;height:8.108108108108109%"></div><button type="button" class="bs-sprite bs-play" data-action="play" aria-label="Play" title="Play"  style="left:43.23886639676113%;top:75%;width:23.076923076923077%;height:20.10135135135135%"><img alt="" draggable="false" src="data:image/png;base64,"></button><span class="bs-servers-label" style="left:26.477732793522268%;top:37.66891891891892%;width:8.906882591093117%;height:5.405405405405405%">Servers</span><p class="bs-message" role="status" style="left:38.46153846153847%;top:67.73648648648648%;width:32.388663967611336%;height:4.5608108108108105%"></p></div>`;
 host.querySelector('[data-slot=nickname]').appendChild(nickname);host.querySelector('[data-slot=servers]').appendChild(servers);document.body.appendChild(host);
 const play=host.querySelector('[data-action=play]'),message=host.querySelector('.bs-message');
 let locked=false,resetTimer=null;
 const update=()=>{const visible=nickname.style.display!=='none'&&!nickname.hidden;host.hidden=!visible;for(const button of host.querySelectorAll('[aria-pressed]'))button.setAttribute('aria-pressed',String(button.dataset.action===(['private','official','community'].includes(button.dataset.action)?actions.kind():actions.mode())));if(!actions.busy()&&locked){locked=false;play.disabled=false;message.textContent='';if(resetTimer){clearTimeout(resetTimer);resetTimer=null;}}};
 host.addEventListener('click',event=>{const button=event.target.closest('button[data-action]');if(!button||button.disabled)return;event.preventDefault();const action=button.dataset.action;try{if(action==='community'){actions.community();update();return;}if(action==='play'){if(locked||actions.busy())return;locked=true;play.disabled=true;message.textContent='Connecting…';resetTimer=setTimeout(()=>{resetTimer=null;locked=false;play.disabled=false;message.textContent='';},12000);}actions[action]();update();}catch(error){locked=false;play.disabled=false;message.textContent='Connection unavailable. Try again.';console.error('[BestScript home]',error);}});
 host.addEventListener('keydown',event=>{if(event.target.matches('input,select')){event.stopPropagation();if(event.key==='Enter'&&event.target.id==='nicknameInput'){event.preventDefault();play.click();}}});
 host.addEventListener('keyup',event=>{if(event.target.matches('input,select'))event.stopPropagation();});
 for(const type of ['mousedown','mouseup','pointerdown','pointerup','click','dblclick','touchstart','touchend','wheel'])host.addEventListener(type,event=>event.stopPropagation());
 const observer=new MutationObserver(update);observer.observe(nickname,{attributes:true,attributeFilter:['style','hidden']});observer.observe(servers,{childList:true,subtree:true});
 window.__bestScriptHome={get visible(){return !host.hidden;},element:host,refresh:update};update();
 };
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
}
